'use client'

import React, { useState } from 'react'
import {
  Alert,
  Badge,
  Button,
  Card,
  Container,
  Form,
  Spinner
} from 'react-bootstrap'

interface Section {
  id: number
  title: string
  anchor: string
}

interface Proposal {
  title: string
  reason: string
  sectionIds: number[]
  status: string
  selected: boolean
}

interface Analysis {
  alias: string
  sourceTitle: string
  sectionCount: number
  sections: Section[]
  summary: string
  proposals: Omit<Proposal, 'selected'>[]
}

interface CreatedNote {
  title: string
  status: string
  alias: string
  url: string
}

export default function SplitNotesPage() {
  const [source, setSource] = useState('')
  const [analysis, setAnalysis] =
    useState<Analysis | null>(null)
  const [proposals, setProposals] =
    useState<Proposal[]>([])
  const [created, setCreated] =
    useState<CreatedNote[]>([])
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [message, setMessage] = useState('')

  async function analyze() {
    setBusy(true)
    setError('')
    setMessage('')
    setCreated([])

    try {
      const response = await fetch(
        '/memex-split-notes',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            action: 'analyze',
            source
          })
        }
      )

      const body = await response.json()

      if (!response.ok) {
        throw new Error(
          body.error ?? `HTTP ${response.status}`
        )
      }

      const result = body as Analysis

      setAnalysis(result)

      setProposals(
        result.proposals.map((proposal) => ({
          ...proposal,
          status: proposal.status ?? 'draft',
          selected: true
        }))
      )
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Analysis failed'
      )
    } finally {
      setBusy(false)
    }
  }

  function patchProposal(
    index: number,
    patch: Partial<Proposal>
  ) {
    setProposals((current) =>
      current.map((proposal, i) =>
        i === index
          ? { ...proposal, ...patch }
          : proposal
      )
    )
  }

  async function createSelected() {
    const selected = proposals.filter(
      (proposal) => proposal.selected
    )

    if (selected.length === 0) return

    setBusy(true)
    setError('')
    setMessage('')
    setCreated([])

    try {
      const response = await fetch(
        '/memex-split-notes',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            action: 'create',
            source,
            proposals: selected.map(
              ({
                title,
                reason,
                sectionIds,
                status
              }) => ({
                title,
                reason,
                sectionIds,
                status
              })
            )
          })
        }
      )

      const body = await response.json()

      if (!response.ok) {
        throw new Error(
          body.error ?? `HTTP ${response.status}`
        )
      }

      setCreated(body.created ?? [])

      const failed = body.failures?.length ?? 0

      setMessage(
        `${body.created?.length ?? 0} HedgeDoc(s) created` +
          (failed
            ? `; ${failed} failed.`
            : '.')
      )

      if (failed) {
        setError(
          body.failures
            .map(
              (failure: {
                title: string
                error: string
              }) =>
                `${failure.title}: ${failure.error}`
            )
            .join('\n')
        )
      }
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Create failed'
      )
    } finally {
      setBusy(false)
    }
  }

  const sectionMap = new Map(
    analysis?.sections.map((section) => [
      section.id,
      section
    ]) ?? []
  )

  const selectedCount = proposals.filter(
    (proposal) => proposal.selected
  ).length

  return (
    <Container className='py-4'>
      <div className='mb-4'>
        <h1>LLM Split HedgeDoc</h1>

        <p className='text-muted'>
          One existing HedgeDoc → LLM decides how many
          useful standalone HedgeDocs should be created.
          You review the plan and choose the status of
          each new note before creation.
        </p>
      </div>

      <Card className='mb-4'>
        <Card.Body>
          <Form.Label>
            Existing HedgeDoc URL or alias
          </Form.Label>

          <div className='d-flex gap-2'>
            <Form.Control
              value={source}
              disabled={busy}
              placeholder='http://192.168.1.142:8180/n/...'
              onChange={(event) =>
                setSource(event.target.value)
              }
            />

            <Button
              onClick={analyze}
              disabled={busy || !source.trim()}>
              {busy && (
                <Spinner
                  size='sm'
                  className='me-2'
                />
              )}
              Analyze with LLM
            </Button>
          </div>
        </Card.Body>
      </Card>

      {error && (
        <Alert
          variant='danger'
          style={{ whiteSpace: 'pre-wrap' }}>
          {error}
        </Alert>
      )}

      {message && (
        <Alert variant='success'>
          {message}
        </Alert>
      )}

      {analysis && (
        <>
          <div className='d-flex flex-wrap align-items-center gap-2 mb-3'>
            <h2 className='mb-0'>
              {analysis.sourceTitle}
            </h2>

            <Badge bg='secondary'>
              {analysis.sectionCount} source sections
            </Badge>

            <Badge bg='primary'>
              LLM recommends {proposals.length}{' '}
              HedgeDoc{proposals.length === 1 ? '' : 's'}
            </Badge>
          </div>

          {analysis.summary && (
            <Alert variant='info'>
              {analysis.summary}
            </Alert>
          )}

          {proposals.map((proposal, index) => (
            <Card
              key={index}
              className='mb-3'>
              <Card.Body>
                <div className='d-flex gap-3'>
                  <Form.Check
                    type='checkbox'
                    checked={proposal.selected}
                    disabled={busy}
                    onChange={(event) =>
                      patchProposal(index, {
                        selected:
                          event.target.checked
                      })
                    }
                  />

                  <div className='flex-grow-1'>
                    <div className='row g-3'>
                      <div className='col-md-8'>
                        <Form.Label>
                          New HedgeDoc title
                        </Form.Label>

                        <Form.Control
                          value={proposal.title}
                          disabled={busy}
                          onChange={(event) =>
                            patchProposal(index, {
                              title:
                                event.target.value
                            })
                          }
                        />
                      </div>

                      <div className='col-md-4'>
                        <Form.Label>
                          Status
                        </Form.Label>

                        <Form.Select
                          value={proposal.status}
                          disabled={busy}
                          onChange={(event) =>
                            patchProposal(index, {
                              status:
                                event.target.value
                            })
                          }>
                          <option value='draft'>
                            draft
                          </option>
                          <option value='stable'>
                            stable
                          </option>
                          <option value='experimental'>
                            experimental
                          </option>
                        </Form.Select>
                      </div>
                    </div>

                    <p className='mt-3 mb-2'>
                      {proposal.reason}
                    </p>

                    <div className='small text-muted'>
                      Source sections:
                    </div>

                    <div className='d-flex flex-wrap gap-2 mt-1'>
                      {proposal.sectionIds.map(
                        (sectionId) => {
                          const section =
                            sectionMap.get(sectionId)

                          return (
                            <Badge
                              bg='secondary'
                              key={sectionId}>
                              {section
                                ? `${sectionId}. ${section.title}`
                                : `Section ${sectionId}`}
                            </Badge>
                          )
                        }
                      )}
                    </div>
                  </div>
                </div>
              </Card.Body>
            </Card>
          ))}

          <div className='d-flex justify-content-end mb-4'>
            <Button
              variant='success'
              size='lg'
              disabled={
                busy || selectedCount === 0
              }
              onClick={createSelected}>
              {busy && (
                <Spinner
                  size='sm'
                  className='me-2'
                />
              )}
              Create Selected ({selectedCount})
            </Button>
          </div>
        </>
      )}

      {created.length > 0 && (
        <Card>
          <Card.Header>
            Created HedgeDocs
          </Card.Header>

          <Card.Body>
            {created.map((note) => (
              <div
                key={note.alias}
                className='mb-2'>
                <a
                  href={note.url}
                  target='_blank'
                  rel='noreferrer'>
                  {note.title}
                </a>{' '}
                <Badge
                  bg={
                    note.status === 'stable'
                      ? 'success'
                      : note.status ===
                          'experimental'
                        ? 'warning'
                        : 'secondary'
                  }>
                  {note.status}
                </Badge>
              </div>
            ))}
          </Card.Body>
        </Card>
      )}
    </Container>
  )
}
